import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.BfI5QxtK.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),s={name:"troubleshooting.md"};function o(r,e,l,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start with the symptom. Keep the exact error and <code>gnoblinctl version</code> output when reporting a problem.</p><h2 id="gnoblin-is-missing-from-the-login-screen" tabindex="-1">Gnoblin is missing from the login screen <a class="header-anchor" href="#gnoblin-is-missing-from-the-login-screen" aria-label="Permalink to &quot;Gnoblin is missing from the login screen&quot;">​</a></h2><p>For Fedora, check the session package:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnoblin-session</span></span></code></pre></div><p>For source builds, complete <a href="./install-source#3-add-a-login-session">session registration</a>, including the printed root commands. Building alone does not add a login entry.</p><h2 id="no-bar-dock-or-launcher" tabindex="-1">No bar, dock or launcher <a class="header-anchor" href="#no-bar-dock-or-launcher" aria-label="Permalink to &quot;No bar, dock or launcher&quot;">​</a></h2><p>Gnoblin does not include a desktop shell. <a href="./bring-your-own-shell">Install one</a> if you have not already.</p><p>Right-click the desktop to open a terminal. With no visible layer surface, the recovery panel appears after eight seconds. It cannot detect a frozen shell that still has a visible surface.</p><p>For Bingux:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bingux.service</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bingux.service</span></span></code></pre></div><p>A Qt/Quickshell version mismatch requires rebuilding or installing a matching Quickshell package. Restarting repeatedly will not fix that mismatch.</p><h2 id="a-config-edit-does-nothing" tabindex="-1">A config edit does nothing <a class="header-anchor" href="#a-config-edit-does-nothing" aria-label="Permalink to &quot;A config edit does nothing&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><p>Edit the printed path and read the reload error. Then check:</p><ul><li>Does this setting need a <a href="/gnoblin/guides/files_and_load_order#reload-and-persistence">new session</a>?</li><li>Is a function missing? See <a href="#gnoblin-or-configure-is-nil">configuration compatibility</a>.</li><li>Did an unmatched include glob load nothing?</li><li>Did a later list replace your rules or shortcuts?</li></ul><h2 id="gnoblin-or-configure-is-nil" tabindex="-1"><code>gnoblin</code> or <code>configure</code> is nil <a class="header-anchor" href="#gnoblin-or-configure-is-nil" aria-label="Permalink to &quot;`gnoblin` or `configure` is nil&quot;">​</a></h2><p>An error such as <code>attempt to index a nil value (global &#39;gnoblin&#39;)</code> or <code>attempt to call a nil value (field &#39;configure&#39;)</code> can mean your running compositor predates the Lua functions used in these guides.</p><p>If you have just updated Gnoblin, log out and back in. Reloading the config does not load an updated compositor. Otherwise, update through your <a href="./installation">installation method</a>. If your package does not include these functions, keep using the <a href="/gnoblin/guides/files_and_load_order#existing-configs">existing config syntax</a> or <a href="./install-source">build from source</a>.</p><p>On a build that supports these functions, check that your config has not assigned another value to <code>gnoblin</code> or <code>gnoblin.configure</code>.</p><h2 id="my-component-s-shortcuts-or-rules-disappeared" tabindex="-1">My component&#39;s shortcuts or rules disappeared <a class="header-anchor" href="#my-component-s-shortcuts-or-rules-disappeared" aria-label="Permalink to &quot;My component&#39;s shortcuts or rules disappeared&quot;">​</a></h2><p>Nonempty lists in <code>gnoblin.configure</code> replace earlier lists. <a href="/gnoblin/guides/files_and_load_order#override-or-append">Append to the existing list</a> or edit its entries after the component loads.</p><h2 id="a-window-rule-does-not-match" tabindex="-1">A window rule does not match <a class="header-anchor" href="#a-window-rule-does-not-match" aria-label="Permalink to &quot;A window rule does not match&quot;">​</a></h2><p>Every matcher must match. Text matchers use JavaScript regex, not Lua patterns. Check anchors, escaping and the raw app ID. See <a href="/gnoblin/guides/window_rules">window rules</a>.</p><h2 id="a-shortcut-fails" tabindex="-1">A shortcut fails <a class="header-anchor" href="#a-shortcut-fails" aria-label="Permalink to &quot;A shortcut fails&quot;">​</a></h2><p>Run its command in a terminal. Check that the executable is on PATH. Command arguments do not expand <code>~</code>, <code>$HOME</code> or pipes.</p><p>Check for an existing binding in your component config or GNOME keybindings. See <a href="/gnoblin/guides/shortcuts#avoid-conflicts">shortcut conflicts</a>.</p><h2 id="shell-integration-errors" tabindex="-1">Shell integration errors <a class="header-anchor" href="#shell-integration-errors" aria-label="Permalink to &quot;Shell integration errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td><code>gnoblinctl window list</code> cannot connect</td><td>Run <code>gnoblinctl status --json</code>. Check <code>windowControlError</code> and the active socket path. The bridge is built into current source builds; it does not appear in <code>script list</code>. See <a href="./gnoblinctl#connection-problems">connection details</a>.</td></tr><tr><td>A bridge request says a window is unavailable</td><td>Get a fresh ID from <code>gnoblinctl window list --json</code> or a <code>windows</code> snapshot. IDs expire when windows close.</td></tr><tr><td>A Wayland client cannot bind a Gnoblin interface</td><td>Inspect the registry inside the Gnoblin session, then check its <a href="./wayland-protocols">protocol gate</a>. Gates take effect at login, not config reload.</td></tr><tr><td>A layer appears on the host desktop during devkit work</td><td>Launch it from the devkit environment and check <code>WAYLAND_DISPLAY</code>. The <a href="./devkit">devkit guide</a> explains the nested display.</td></tr></tbody></table><h2 id="removing-a-setting-does-not-reset-it" tabindex="-1">Removing a setting does not reset it <a class="header-anchor" href="#removing-a-setting-does-not-reset-it" aria-label="Permalink to &quot;Removing a setting does not reset it&quot;">​</a></h2><p>Built-in bindings and native feature booleans persist in GSettings. Set the desired value explicitly. Removing an autostart entry does not stop its running process.</p><h2 id="blur-is-invisible" tabindex="-1">Blur is invisible <a class="header-anchor" href="#blur-is-invisible" aria-label="Permalink to &quot;Blur is invisible&quot;">​</a></h2><p>The application or panel must draw a translucent background. Rule opacity fades text too; it does not replace client background transparency. See <a href="/gnoblin/guides/window_effects#blur-and-opacity">blur</a>.</p><h2 id="there-are-two-titlebars-or-none" tabindex="-1">There are two titlebars, or none <a class="header-anchor" href="#there-are-two-titlebars-or-none" aria-label="Permalink to &quot;There are two titlebars, or none&quot;">​</a></h2><p>Check your <a href="/gnoblin/guides/window_frames#choose-a-mode">frame mode</a>. A renderer name alone does not enable SSD, and an unset protocol preference does not prove that the client draws a titlebar.</p><h2 id="read-the-logs" tabindex="-1">Read the logs <a class="header-anchor" href="#read-the-logs" aria-label="Permalink to &quot;Read the logs&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;10 minutes ago&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;gnoblin-config|gnoblin-shader&#39;</span></span></code></pre></div><p>Restore a saved working config and reload to undo file changes. This does not undo launched processes or persistent GSettings values.</p>',38)])])}const u=i(s,[["render",o]]);export{g as __pageData,u as default};
